//! Minimal URL percent-encoding/decoding and parsing utilities.
//!
//! Re-implementation of the behavior of the C++ `url_parser` library used by
//! `test17.cpp`, inferred from the reference binary's observable behavior.

/// Characters that are left unencoded (RFC 3986 unreserved set).
fn is_unreserved(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~')
}

/// Percent-encode every non-unreserved byte using lowercase hex digits.
pub fn url_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    const HEX: &[u8; 16] = b"0123456789abcdef";
    for &b in s.as_bytes() {
        if is_unreserved(b) {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0f) as usize] as char);
        }
    }
    out
}

fn hex_value(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

/// Decode percent-escapes (`%xx`, case-insensitive hex) and treat `+` as a
/// space. Invalid or truncated `%` sequences are left untouched.
pub fn url_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' if i + 2 < bytes.len() + 1 && i + 2 <= bytes.len() - 1 + 1 => {
                // Guarded below; this arm only entered when two more bytes exist.
                unreachable!()
            }
            b'%' => {
                if i + 2 < bytes.len() + 1 && i + 2 <= bytes.len() {
                    if let (Some(hi), Some(lo)) =
                        (hex_value(bytes[i + 1]), hex_value(bytes[i + 2]))
                    {
                        out.push((hi << 4) | lo);
                        i += 3;
                        continue;
                    }
                }
                out.push(b'%');
                i += 1;
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// A parsed URL exposing the components used by the test program.
pub struct URL {
    scheme: String,
    host: String,
    path: String,
    query: String,
}

impl URL {
    pub fn new(raw: &str) -> URL {
        // scheme
        let (scheme, rest) = match raw.find("://") {
            Some(idx) => (raw[..idx].to_string(), &raw[idx + 3..]),
            None => (String::new(), raw),
        };

        // host ends at the first '/', '?' or '#' after the authority start
        let host_end = rest
            .find(|c| c == '/' || c == '?' || c == '#')
            .unwrap_or(rest.len());
        let host = rest[..host_end].to_string();
        let after_host = &rest[host_end..];

        // path: up to '?' or '#'
        let (path, after_path) = if after_host.starts_with('/') {
            let end = after_host
                .find(|c| c == '?' || c == '#')
                .unwrap_or(after_host.len());
            (after_host[..end].to_string(), &after_host[end..])
        } else {
            (String::new(), after_host)
        };

        // query: after '?' up to '#'
        let query = if let Some(stripped) = after_path.strip_prefix('?') {
            let end = stripped.find('#').unwrap_or(stripped.len());
            stripped[..end].to_string()
        } else {
            String::new()
        };

        URL {
            scheme,
            host,
            path,
            query,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    /// Split the query string on '&', then each pair on the first '='.
    /// Pairs without '=' yield an empty value.
    pub fn query_params(&self) -> Vec<(String, String)> {
        if self.query.is_empty() {
            return Vec::new();
        }
        self.query
            .split('&')
            .map(|pair| match pair.find('=') {
                Some(idx) => (pair[..idx].to_string(), pair[idx + 1..].to_string()),
                None => (pair.to_string(), String::new()),
            })
            .collect()
    }
}

