#[path = "src/url_parser.rs"]
mod url_parser;

use url_parser::{url_decode, url_encode, URL};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let s = &args[1];

    println!("{}", url_encode(s));
    println!("{}", url_decode(s));

    let parser = URL::new(&format!("http://example.com/test?q={}", url_encode(s)));

    println!("{}", parser.scheme());
    println!("{}", parser.host());
    println!("{}", parser.path());
    println!("{}", parser.query());

    for (key, value) in parser.query_params() {
        println!("{}", url_decode(&key));
        println!("{}", url_decode(&value));
    }
}

