#[path = "src/url_parser.rs"]
mod url_parser;

use std::io::Write;
use url_parser::{url_decode, url_encode, URL};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let s = &args[1];

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    let mut line = |bytes: &[u8]| {
        out.write_all(bytes).unwrap();
        out.write_all(b"\n").unwrap();
    };

    line(url_encode(s).as_bytes());
    line(&url_decode(s));

    let parser = URL::new(&format!("http://example.com/test?q={}", url_encode(s)));

    line(parser.scheme().as_bytes());
    line(parser.host().as_bytes());
    line(parser.path().as_bytes());
    line(parser.query().as_bytes());

    for (key, value) in parser.query_params() {
        line(&url_decode(&String::from_utf8_lossy(&key)));
        line(&url_decode(&String::from_utf8_lossy(&value)));
    }
}

